/*Table structure for table `dept` */

DROP TABLE IF EXISTS `dept`;

CREATE TABLE `dept` (
  `name` varchar(100) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

/*Data for the table `dept` */

insert  into `dept`(`name`) values ('cse'),('Civil'),('Mech'),('AIML'),('ECE');

/*Table structure for table `vacancy` */

DROP TABLE IF EXISTS `vacancy`;

CREATE TABLE `vacancy` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `dept` varchar(1000) DEFAULT NULL,
  `job_name` varchar(1000) DEFAULT NULL,
  `experience` varchar(1000) DEFAULT NULL,
  `salary` varchar(1000) DEFAULT NULL,
  `description` varbinary(1000) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=latin1;

/*Data for the table `vacancy` */

insert  into `vacancy`(`id`,`dept`,`job_name`,`experience`,`salary`,`description`) values (6,'cse','Java Developer','0-2 years','100000-450000','code,advance,html,css,springboot');

